<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {api,date,fmt} from '../api';import WorkoutChart from '../components/WorkoutChart.vue';import Metrics from '../components/Metrics.vue'
const props=defineProps<{athlete:any}>();const models=ref<any[]>([]),selected=ref<any>(null),wid=ref(''),part=ref(0),error=ref('')
async function load(){try{models.value=await api(`/athletes/${props.athlete.id}/models`)}catch(e:any){error.value=e.message}}
async function choose(id:string){try{selected.value=await api('/models/'+id);wid.value=selected.value.validation?.workouts[0]?.workout_id||'';part.value=0}catch(e:any){error.value=e.message}}
const workout=computed(()=>selected.value?.validation?.workouts.find((w:any)=>w.workout_id===wid.value))
const segment=computed(()=>workout.value?.parts[part.value])
const metric=computed(()=>workout.value?.metrics.find((m:any)=>m.window==='all'&&m.model==='chain'))
const residual=computed(()=>segment.value?{elapsed:segment.value.series.elapsed,residual:segment.value.series.hr.map((v:any,i:number)=>v==null?null:v-segment.value.series.hr_chain[i])}:null)
onMounted(load)
</script>
<template><div class="page-heading"><div><p class="eyebrow">VERSIONI IMMUTABILI</p><h1>Modelli dell’atleta</h1><p>Periodi, parametri e risultati di ogni identificazione.</p></div></div><div class="error" v-if="error">{{error}}</div><div class="empty" v-if="!models.length"><h2>Nessun modello identificato</h2><p>Crea un esperimento e avvia esplicitamente la prima identificazione.<br>Non vengono riutilizzati i coefficienti di altri atleti.</p></div><div class="version-list"><button v-for="m in models" class="secondary" :class="{chosen:selected?.id===m.id}" @click="choose(m.id)">{{date(m.created_at)}} · {{m.id.slice(0,8)}}</button></div><template v-if="selected"><div class="card"><div class="section-heading"><h2>P1D HR · popolazione individuale</h2><span class="tag good">Congelato</span></div><p>Train {{date(selected.train_period[0])}} — {{date(selected.train_period[1])}} · {{selected.split.train.length}} attività</p><div class="metric-grid"><div v-for="(key,i) in selected.hr.analysis.model.keys"><small>{{key}} {{key==='K'?'bpm/W':'s'}}</small><strong>{{fmt(selected.hr.analysis.model.mean[i],4)}}</strong><small>SD tra tratti {{fmt(selected.hr.analysis.model.sd[i],4)}}</small><small class="block">CI media {{selected.hr.analysis.model.mean_ci95?.[i]?.map((v:any)=>fmt(v,4)).join(' – ')||'non disponibile'}}</small></div><div><small>A train · bpm</small><strong>{{fmt(selected.hr.analysis.B_reference.A)}}</strong></div><div><small>HR0 train · bpm</small><strong>{{fmt(selected.hr.analysis.HR0_reference.mean)}}</strong></div></div><p class="notice">B = A + K·P0. Nessuna finestra HR validation usata per B o HR0. La SD descrive la variabilità tra tratti, non l’incertezza della media.</p><p>Potenza rappresentata {{fmt(selected.domain.power_quantiles_w[0])}}–{{fmt(selected.domain.power_quantiles_w[4])}} W · {{selected.domain.samples}} campioni HR train. Durate tratti {{fmt(Math.min(...selected.domain.segment_durations_s))}}–{{fmt(Math.max(...selected.domain.segment_durations_s))}} s.</p><details><summary>Configurazione, fit, screening e provenienza</summary><pre>{{JSON.stringify({config:selected.config,analysis:selected.hr.analysis,fit:selected.fits,domain:selected.domain,software:selected.software,hash:selected.sha256},null,2)}}</pre></details></div><div class="card"><h2>Validation · risultati fuori training</h2><p class="caption">Target ricostruiti dai dati osservati: confronto retrospettivo. Aggregazione con peso uguale per workout.</p><table><thead><tr><th>Modello HR / supporto</th><th>Workout</th><th>MAE bpm</th><th>RMSE bpm</th><th>Bias bpm</th><th>Copertura</th><th>Larghezza bpm</th></tr></thead><tbody><tr v-for="r in selected.validation.aggregate"><td>{{r.model}} · {{r.window}}</td><td>{{r.workouts}}</td><td>{{fmt(r.MAE)}}</td><td>{{fmt(r.RMSE)}}</td><td>{{fmt(r.bias)}}</td><td>{{fmt(r.coverage)}}</td><td>{{fmt(r.width)}}</td></tr></tbody></table></div><div class="toolbar"><label>Workout validation<select v-model="wid" @change="part=0"><option v-for="w in selected.validation.workouts" :value="w.workout_id">{{w.source_name}} · {{w.status}}</option></select></label><label v-if="workout?.parts.length">Tratto<select v-model="part"><option v-for="(p,i) in workout.parts" :value="i">{{Number(i)+1}} · {{fmt(p.series.time.at(-1))}} s</option></select></label></div><Metrics :value="metric" title="Intero workout · catena HR"/><p class="error" v-for="f in workout?.failures">{{f.segment_id}}: {{f.reason}}</p><WorkoutChart v-if="segment" :series="segment.series" bands/><WorkoutChart v-if="residual" :series="residual" title="Residuo HR · osservato − predetto"/></template></template>
